-- Seed de datos: conciertos y zonas reales de Lima (2026), generado para pruebas end-to-end.
COMMIT;
SELECT c.nombre, TO_CHAR(TO_DATE('19700101','YYYYMMDD') + c.fecha_ms/86400000, 'DD/MM/YYYY') fecha, COUNT(z.id) zonas, SUM(z.capacidad) capacidad_total FROM conciertos c JOIN zonas z ON z.concierto_id = c.id GROUP BY c.nombre, c.fecha_ms ORDER BY c.fecha_ms;
EXIT;